export const browserFiles = {
  "/startup/startup.js": "import { KNOWN_NAMES, showLogin } from \"../setup/login_user.js\";\nimport { constructMainPage } from \"../main_page/construct_main_page.js\";\nimport { constructMenuDesign } from \"../menu_bar/construct_design/construct_design.js\";\nimport { setOnlineUsers } from \"../menu_bar/online_users.js\";\nimport { populateMenu } from \"../menu_bar/populate/populate.js\";\nimport { connectDesk } from \"./desk.js\";\n\n// Procedures this desk calls, in order:\n// 1. readIndexedName()      IndexedDB. Skip login when the name is already there.\n// 2. showLogin()            setup/login_user.js. Dropdown only, then Enter.\n// 3. saveIndexedName()\n// 4. constructMainPage()    main_page/construct_main_page.js\n// 5. constructMenuDesign()  menu bar icon and mega menu\n// 6. connectDesk()          who is logged in\n// 7. setOnlineUsers()       menu_bar/online_users.js keeps the online array\n// 8. populateMenu()         fills the mega menu on every desk update\n\nconst DB_NAME = \"battery_nb_cert_docs\";\nconst STORE = \"session\";\nconst USER_KEY = \"user\";\nconst STORAGE_ID = \"battery_nb_cert_docs.clientId\";\nconst STORAGE_NAME = \"user name\";\nconst LEGACY_NAME = \"battery_nb_cert_docs.userName\";\n\nconst root = document.querySelector(\"#app\");\nconst clientId = loadClientId();\nlet desk = null;\nlet dismissMenu = null;\nlet unwatchOnline = null;\n\nstart().catch((error) => {\n  console.error(error);\n  root.replaceChildren();\n  const message = document.createElement(\"p\");\n  message.className = \"boot-error\";\n  message.textContent = \"The desk could not start.\";\n  root.append(message);\n});\n\nasync function start() {\n  const existing = await readIndexedName();\n  if (existing) {\n    await enterDesk(existing);\n    return;\n  }\n  const name = await askForName();\n  await enterDesk(name);\n}\n\nasync function enterDesk(name) {\n  await saveIndexedName(name);\n  rememberLocalName(name);\n  if (desk) {\n    desk.close();\n    desk = null;\n  }\n\n  if (unwatchOnline) {\n    unwatchOnline();\n    unwatchOnline = null;\n  }\n\n  const page = constructMainPage(root);\n  const menu = constructMenuDesign(page.menuBar, {\n    name,\n    onAnotherName: () => switchName(),\n  });\n  unwatchOnline = menu.unwatchOnline;\n  watchMenu(menu);\n\n  desk = connectDesk({\n    clientId,\n    name,\n    onStatus: menu.setStatus,\n    onUsers(users) {\n      setOnlineUsers(users);\n      populateMenu(menu.list, users, {\n        clientId,\n        count: menu.count,\n        onToggle(targetId) {\n          desk.send({ type: \"toggleUser\", clientId, targetId });\n        },\n      });\n    },\n  });\n}\n\nasync function switchName() {\n  if (desk) {\n    desk.close();\n    desk = null;\n  }\n  if (dismissMenu) {\n    dismissMenu();\n    dismissMenu = null;\n  }\n  await clearIndexedName();\n  forgetLocalName();\n  const name = await askForName();\n  await enterDesk(name);\n}\n\nfunction askForName() {\n  return new Promise((resolve) => {\n    showLogin(root, { onEnter: resolve });\n  });\n}\n\nfunction watchMenu(menu) {\n  if (dismissMenu) dismissMenu();\n  const onPointer = (event) => {\n    if (menu.panel.hidden) return;\n    if (menu.panel.contains(event.target) || menu.button.contains(event.target)) return;\n    menu.close();\n  };\n  const onKey = (event) => {\n    if (event.key === \"Escape\") menu.close();\n  };\n  document.addEventListener(\"pointerdown\", onPointer);\n  document.addEventListener(\"keydown\", onKey);\n  dismissMenu = () => {\n    document.removeEventListener(\"pointerdown\", onPointer);\n    document.removeEventListener(\"keydown\", onKey);\n  };\n}\n\nfunction loadClientId() {\n  let id = localStorage.getItem(STORAGE_ID);\n  if (!id) {\n    id = crypto.randomUUID();\n    localStorage.setItem(STORAGE_ID, id);\n  }\n  return id;\n}\n\nfunction openDb() {\n  return new Promise((resolve, reject) => {\n    const request = indexedDB.open(DB_NAME, 1);\n    request.onupgradeneeded = () => {\n      const db = request.result;\n      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);\n    };\n    request.onsuccess = () => resolve(request.result);\n    request.onerror = () => reject(request.error);\n  });\n}\n\nasync function readIndexedName() {\n  try {\n    const db = await openDb();\n    const name = await new Promise((resolve, reject) => {\n      const tx = db.transaction(STORE, \"readonly\");\n      const get = tx.objectStore(STORE).get(USER_KEY);\n      get.onsuccess = () => resolve(typeof get.result?.name === \"string\" ? get.result.name : \"\");\n      get.onerror = () => reject(get.error);\n    });\n    db.close();\n    return KNOWN_NAMES.includes(name) ? name : \"\";\n  } catch {\n    return \"\";\n  }\n}\n\nasync function saveIndexedName(name) {\n  if (!KNOWN_NAMES.includes(name)) throw new Error(\"Choose a name from the list.\");\n  try {\n    const db = await openDb();\n    await new Promise((resolve, reject) => {\n      const tx = db.transaction(STORE, \"readwrite\");\n      tx.oncomplete = () => resolve();\n      tx.onerror = () => reject(tx.error);\n      tx.objectStore(STORE).put({ name, savedAt: new Date().toISOString() }, USER_KEY);\n    });\n    db.close();\n  } catch {\n    // The desk still opens for this visit. The next open asks again.\n  }\n}\n\nasync function clearIndexedName() {\n  try {\n    const db = await openDb();\n    await new Promise((resolve, reject) => {\n      const tx = db.transaction(STORE, \"readwrite\");\n      tx.oncomplete = () => resolve();\n      tx.onerror = () => reject(tx.error);\n      tx.objectStore(STORE).delete(USER_KEY);\n    });\n    db.close();\n  } catch {\n    // Login still shows if the store cannot be cleared.\n  }\n}\n\nfunction rememberLocalName(name) {\n  localStorage.setItem(STORAGE_NAME, name);\n  localStorage.setItem(LEGACY_NAME, name);\n}\n\nfunction forgetLocalName() {\n  localStorage.removeItem(STORAGE_NAME);\n  localStorage.removeItem(LEGACY_NAME);\n}\n",
  "/startup/desk.js": "export function connectDesk({ clientId, name, onUsers, onStatus }) {\n  let socket = null;\n  let retry = 0;\n  let stopped = false;\n  let timer = 0;\n  let currentName = name;\n\n  function send(payload) {\n    if (!socket || socket.readyState !== WebSocket.OPEN) return;\n    socket.send(JSON.stringify(payload));\n  }\n\n  function connect() {\n    if (stopped) return;\n    const proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n    socket = new WebSocket(`${proto}//${location.host}/ws`);\n    onStatus(\"Connecting\", \"\");\n\n    socket.addEventListener(\"open\", () => {\n      retry = 0;\n      onStatus(\"Live\", \"live\");\n      send({ type: \"hello\" });\n      if (currentName) send({ type: \"addUser\", clientId, name: currentName });\n    });\n\n    socket.addEventListener(\"message\", (event) => {\n      let data;\n      try {\n        data = JSON.parse(event.data);\n      } catch {\n        return;\n      }\n      if (data.type === \"error\") {\n        onStatus(data.error || \"Could not join\", \"down\");\n        return;\n      }\n      if (Array.isArray(data.users)) onUsers(data.users);\n    });\n\n    socket.addEventListener(\"close\", () => {\n      if (stopped) return;\n      onStatus(\"Reconnecting\", \"down\");\n      const wait = Math.min(8000, 500 * 2 ** retry);\n      retry += 1;\n      timer = setTimeout(connect, wait);\n    });\n  }\n\n  const ping = setInterval(() => send({ type: \"ping\" }), 25000);\n  connect();\n\n  return {\n    send,\n    setName(next) {\n      currentName = next;\n      send({ type: \"addUser\", clientId, name: next });\n    },\n    close() {\n      stopped = true;\n      clearInterval(ping);\n      clearTimeout(timer);\n      if (socket && socket.readyState < WebSocket.CLOSING) socket.close();\n    },\n  };\n}\n",
  "/setup/login_user.js": "export const KNOWN_NAMES = [\"Judy\", \"Marcus\", \"Wei\", \"Walter\"];\n\nconst STORAGE_NAME = \"user name\";\nconst LEGACY_NAME = \"battery_nb_cert_docs.userName\";\n\nexport function showLogin(root, { onEnter }) {\n  root.replaceChildren();\n\n  const gate = document.createElement(\"main\");\n  gate.className = \"gate\";\n\n  const card = document.createElement(\"section\");\n  card.className = \"panel gate-card\";\n\n  const kicker = document.createElement(\"p\");\n  kicker.className = \"kicker\";\n  kicker.textContent = \"Notified body floor\";\n\n  const title = document.createElement(\"h1\");\n  title.textContent = \"Battery NB Cert Desk\";\n\n  const lede = document.createElement(\"p\");\n  lede.className = \"lede\";\n  lede.textContent = \"Choose your name and press Enter. This browser skips this step once that name is stored.\";\n\n  const form = document.createElement(\"form\");\n  form.id = \"join\";\n\n  const label = document.createElement(\"label\");\n  label.htmlFor = \"known-name\";\n  label.textContent = \"Your name\";\n\n  const select = document.createElement(\"select\");\n  select.id = \"known-name\";\n  select.name = \"name\";\n  select.required = true;\n\n  const placeholder = document.createElement(\"option\");\n  placeholder.value = \"\";\n  placeholder.textContent = \"Choose a name\";\n  select.append(placeholder);\n  for (const name of KNOWN_NAMES) {\n    const option = document.createElement(\"option\");\n    option.value = name;\n    option.textContent = name;\n    select.append(option);\n  }\n\n  const remembered = readRememberedName();\n  if (KNOWN_NAMES.includes(remembered)) select.value = remembered;\n\n  const button = document.createElement(\"button\");\n  button.type = \"submit\";\n  button.textContent = \"Enter\";\n  button.disabled = !KNOWN_NAMES.includes(select.value);\n\n  select.addEventListener(\"change\", () => {\n    button.disabled = !KNOWN_NAMES.includes(select.value);\n  });\n\n  form.addEventListener(\"submit\", (event) => {\n    event.preventDefault();\n    if (!KNOWN_NAMES.includes(select.value)) return;\n    onEnter(select.value);\n  });\n\n  form.append(label, select, button);\n  card.append(kicker, title, lede, form);\n  gate.append(card);\n  root.append(gate);\n  select.focus();\n}\n\nfunction readRememberedName() {\n  try {\n    return localStorage.getItem(STORAGE_NAME) || localStorage.getItem(LEGACY_NAME) || \"\";\n  } catch {\n    return \"\";\n  }\n}\n",
  "/main_page/construct_main_page.js": "import { DEMO_TREE, demoCopy } from \"./demo_tree.js\";\n\nexport function constructMainPage(root) {\n  root.replaceChildren();\n\n  const app = document.createElement(\"div\");\n  app.className = \"app\";\n\n  const menuBar = document.createElement(\"header\");\n  menuBar.className = \"menu-bar\";\n\n  const workspace = document.createElement(\"div\");\n  workspace.className = \"workspace\";\n\n  const tree = document.createElement(\"aside\");\n  tree.className = \"tree-container\";\n  tree.setAttribute(\"aria-label\", \"Document tree\");\n\n  const slider = document.createElement(\"div\");\n  slider.className = \"slider\";\n  slider.tabIndex = 0;\n  slider.setAttribute(\"role\", \"separator\");\n  slider.setAttribute(\"aria-orientation\", \"vertical\");\n  slider.setAttribute(\"aria-label\", \"Resize tree and content\");\n  slider.setAttribute(\"aria-valuemin\", \"180\");\n  slider.setAttribute(\"aria-valuemax\", \"560\");\n  slider.setAttribute(\"aria-valuenow\", \"300\");\n\n  const content = document.createElement(\"section\");\n  content.className = \"content-container\";\n  content.setAttribute(\"aria-live\", \"polite\");\n\n  workspace.append(tree, slider, content);\n  app.append(menuBar, workspace);\n  root.append(app);\n\n  renderTree(tree, content);\n  showIntro(content);\n  attachSlider(slider, tree, workspace);\n\n  return { app, menuBar, tree, content, slider, workspace };\n}\n\nfunction renderTree(tree, content) {\n  const label = document.createElement(\"p\");\n  label.className = \"tree-label\";\n  label.textContent = \"Tree\";\n\n  const nav = document.createElement(\"nav\");\n  for (const rootNode of DEMO_TREE) {\n    const group = document.createElement(\"div\");\n    group.className = \"tree-group\";\n\n    const toggle = document.createElement(\"button\");\n    toggle.type = \"button\";\n    toggle.className = \"tree-root\";\n    toggle.setAttribute(\"aria-expanded\", \"true\");\n    const chev = document.createElement(\"span\");\n    chev.className = \"chev\";\n    chev.setAttribute(\"aria-hidden\", \"true\");\n    const text = document.createElement(\"span\");\n    text.textContent = rootNode.label;\n    toggle.append(chev, text);\n\n    const kids = document.createElement(\"div\");\n    kids.className = \"tree-children\";\n    toggle.addEventListener(\"click\", () => {\n      const open = toggle.getAttribute(\"aria-expanded\") !== \"true\";\n      toggle.setAttribute(\"aria-expanded\", open ? \"true\" : \"false\");\n      kids.hidden = !open;\n    });\n\n    for (const child of rootNode.children) {\n      const button = document.createElement(\"button\");\n      button.type = \"button\";\n      button.className = \"tree-child\";\n      button.textContent = child.label;\n      button.addEventListener(\"click\", () => {\n        for (const current of tree.querySelectorAll(\".tree-child[aria-current='true']\")) {\n          current.removeAttribute(\"aria-current\");\n        }\n        button.setAttribute(\"aria-current\", \"true\");\n        showDemo(content, rootNode, child);\n      });\n      kids.append(button);\n    }\n\n    group.append(toggle, kids);\n    nav.append(group);\n  }\n\n  tree.append(label, nav);\n}\n\nfunction showIntro(content) {\n  content.replaceChildren();\n  const article = document.createElement(\"article\");\n  article.className = \"note\";\n  const kicker = document.createElement(\"p\");\n  kicker.className = \"kicker\";\n  kicker.textContent = \"Content\";\n  const heading = document.createElement(\"h1\");\n  heading.textContent = \"Choose a child node\";\n  const copy = document.createElement(\"p\");\n  copy.textContent = \"The tree is a demo. Select a child and its note opens in this pane.\";\n  article.append(kicker, heading, copy);\n  content.append(article);\n}\n\nfunction showDemo(content, rootNode, child) {\n  content.replaceChildren();\n  const article = document.createElement(\"article\");\n  article.className = \"note\";\n  const kicker = document.createElement(\"p\");\n  kicker.className = \"kicker\";\n  kicker.textContent = rootNode.label;\n  const heading = document.createElement(\"h1\");\n  heading.textContent = child.label;\n  const copy = document.createElement(\"p\");\n  copy.textContent = demoCopy(rootNode, child);\n  article.append(kicker, heading, copy);\n  content.append(article);\n}\n\nfunction attachSlider(slider, tree, workspace) {\n  const narrow = window.matchMedia(\"(max-width: 720px)\");\n  let dragging = false;\n\n  function stacked() {\n    return narrow.matches;\n  }\n\n  function applyMode() {\n    const isStacked = stacked();\n    workspace.classList.toggle(\"stacked\", isStacked);\n    slider.setAttribute(\"aria-orientation\", isStacked ? \"horizontal\" : \"vertical\");\n    if (isStacked) {\n      tree.style.width = \"\";\n      if (!tree.style.height) tree.style.height = \"42%\";\n    } else {\n      tree.style.height = \"\";\n      if (!tree.style.width) tree.style.width = \"300px\";\n    }\n  }\n\n  function setSize(clientX, clientY) {\n    const rect = workspace.getBoundingClientRect();\n    if (stacked()) {\n      const next = Math.min(Math.max(clientY - rect.top, 120), rect.height - 160);\n      tree.style.height = `${next}px`;\n      slider.setAttribute(\"aria-valuenow\", String(Math.round(next)));\n      return;\n    }\n    const next = Math.min(Math.max(clientX - rect.left, 180), Math.min(560, rect.width - 220));\n    tree.style.width = `${next}px`;\n    slider.setAttribute(\"aria-valuenow\", String(Math.round(next)));\n  }\n\n  slider.addEventListener(\"pointerdown\", (event) => {\n    dragging = true;\n    slider.setPointerCapture(event.pointerId);\n    setSize(event.clientX, event.clientY);\n  });\n  slider.addEventListener(\"pointermove\", (event) => {\n    if (!dragging) return;\n    setSize(event.clientX, event.clientY);\n  });\n  slider.addEventListener(\"pointerup\", () => {\n    dragging = false;\n  });\n  slider.addEventListener(\"pointercancel\", () => {\n    dragging = false;\n  });\n  slider.addEventListener(\"keydown\", (event) => {\n    const step = event.shiftKey ? 48 : 16;\n    const current = stacked()\n      ? Number.parseFloat(tree.style.height) || tree.getBoundingClientRect().height\n      : Number.parseFloat(tree.style.width) || tree.getBoundingClientRect().width;\n    if (event.key === \"ArrowLeft\" || event.key === \"ArrowUp\") {\n      event.preventDefault();\n      const rect = workspace.getBoundingClientRect();\n      if (stacked()) setSize(0, rect.top + current - step);\n      else setSize(rect.left + current - step, 0);\n    }\n    if (event.key === \"ArrowRight\" || event.key === \"ArrowDown\") {\n      event.preventDefault();\n      const rect = workspace.getBoundingClientRect();\n      if (stacked()) setSize(0, rect.top + current + step);\n      else setSize(rect.left + current + step, 0);\n    }\n  });\n\n  narrow.addEventListener(\"change\", applyMode);\n  applyMode();\n}\n",
  "/main_page/demo_tree.js": "export const DEMO_TREE = [\n  {\n    id: \"iso-17065\",\n    label: \"ISO/IEC 17065\",\n    children: [\n      { id: \"impartiality\", label: \"Impartiality\" },\n      { id: \"competence\", label: \"Competence\" },\n      { id: \"agreement\", label: \"Certification agreement\" },\n      { id: \"decision\", label: \"Decision making\" },\n      { id: \"public-info\", label: \"Public information\" },\n      { id: \"complaints\", label: \"Complaints\" },\n      { id: \"management\", label: \"Management system\" },\n    ],\n  },\n  {\n    id: \"reg-2023-1542\",\n    label: \"Regulation (EU) 2023/1542\",\n    children: [\n      { id: \"scope\", label: \"Scope and categories\" },\n      { id: \"conformity\", label: \"Conformity assessment\" },\n      { id: \"nb-duties\", label: \"Notified body duties\" },\n      { id: \"carbon\", label: \"Carbon footprint\" },\n      { id: \"diligence\", label: \"Due diligence\" },\n      { id: \"labelling\", label: \"Labelling\" },\n    ],\n  },\n  {\n    id: \"technical-file\",\n    label: \"Technical documentation\",\n    children: [\n      { id: \"model\", label: \"Battery model\" },\n      { id: \"tests\", label: \"Test reports\" },\n      { id: \"performance\", label: \"Performance data\" },\n      { id: \"safety\", label: \"Safety evidence\" },\n      { id: \"recycled\", label: \"Recycled content\" },\n      { id: \"supply\", label: \"Supply chain\" },\n      { id: \"changes\", label: \"Change control\" },\n    ],\n  },\n  {\n    id: \"audit-programme\",\n    label: \"Audit programme\",\n    children: [\n      { id: \"application\", label: \"Application review\" },\n      { id: \"stage-1\", label: \"Stage 1\" },\n      { id: \"stage-2\", label: \"Stage 2\" },\n      { id: \"witness\", label: \"Witnessing\" },\n      { id: \"surveillance\", label: \"Surveillance\" },\n      { id: \"findings\", label: \"Findings\" },\n    ],\n  },\n  {\n    id: \"desk-tasks\",\n    label: \"Desk tasks\",\n    children: [\n      { id: \"walter\", label: \"Walter\" },\n      { id: \"judy\", label: \"Judy\" },\n      { id: \"marcus\", label: \"Marcus\" },\n      { id: \"wei\", label: \"Wei\" },\n      { id: \"open-items\", label: \"Open items\" },\n      { id: \"color-status\", label: \"Color status\" },\n      { id: \"handover\", label: \"Handover\" },\n    ],\n  },\n];\n\nexport function demoCopy(root, child) {\n  return `${child.label} is a demo note under ${root.label}. Nothing is filed here yet. The content pane shows this text so the tree can be checked. Choose another child and this note is replaced.`;\n}\n",
  "/menu_bar/construct_design/construct_design.js": "import { watchOnlineUsers } from \"../online_users.js\";\n\nconst HEADS_SVG = `<svg class=\"heads-svg\" viewBox=\"0 0 48 32\" aria-hidden=\"true\" focusable=\"false\">\n  <g fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n    <circle cx=\"11\" cy=\"11\" r=\"4.2\" opacity=\"0.45\"/>\n    <path d=\"M4.2 27.5c.7-5 3.4-7.6 6.8-7.6s6.1 2.6 6.8 7.6\" opacity=\"0.45\"/>\n    <circle cx=\"37\" cy=\"11\" r=\"4.2\" opacity=\"0.45\"/>\n    <path d=\"M30.2 27.5c.7-5 3.4-7.6 6.8-7.6s6.1 2.6 6.8 7.6\" opacity=\"0.45\"/>\n    <circle cx=\"24\" cy=\"12.2\" r=\"5.1\"/>\n    <path d=\"M14.2 29.2c1.1-6.4 4.7-9.4 9.8-9.4s8.7 3 9.8 9.4\"/>\n  </g>\n</svg>`;\n\nexport function constructMenuDesign(menuBar, { name, onAnotherName }) {\n  menuBar.replaceChildren();\n\n  const bar = document.createElement(\"div\");\n  bar.className = \"menu-bar-inner\";\n\n  const brand = document.createElement(\"div\");\n  brand.className = \"brand\";\n  const kicker = document.createElement(\"p\");\n  kicker.className = \"brand-kicker\";\n  kicker.textContent = \"Notified body\";\n  const title = document.createElement(\"p\");\n  title.className = \"brand-title\";\n  title.textContent = \"Battery NB\";\n  brand.append(kicker, title);\n\n  const status = document.createElement(\"p\");\n  status.className = \"status\";\n  status.textContent = \"Connecting\";\n\n  const field = document.createElement(\"div\");\n  field.className = \"signed-field\";\n  const fieldLabel = document.createElement(\"span\");\n  fieldLabel.textContent = \"Signed in\";\n  const fieldName = document.createElement(\"strong\");\n  fieldName.textContent = name;\n  field.append(fieldLabel, fieldName);\n\n  const button = document.createElement(\"button\");\n  button.type = \"button\";\n  button.className = \"heads\";\n  button.setAttribute(\"aria-haspopup\", \"dialog\");\n  button.setAttribute(\"aria-expanded\", \"false\");\n  button.setAttribute(\"aria-controls\", \"desk-menu\");\n\n  const face = document.createElement(\"span\");\n  face.className = \"heads-face\";\n  face.innerHTML = HEADS_SVG;\n  const onlineCount = document.createElement(\"span\");\n  onlineCount.className = \"heads-count\";\n  onlineCount.setAttribute(\"aria-hidden\", \"true\");\n  onlineCount.textContent = \"0\";\n  face.append(onlineCount);\n  button.append(face);\n\n  const anchor = document.createElement(\"div\");\n  anchor.className = \"menu-anchor\";\n\n  const panel = document.createElement(\"div\");\n  panel.className = \"mega\";\n  panel.id = \"desk-menu\";\n  panel.hidden = true;\n  panel.setAttribute(\"role\", \"dialog\");\n  panel.setAttribute(\"aria-label\", \"People on the desk\");\n\n  const head = document.createElement(\"div\");\n  head.className = \"mega-head\";\n  const heading = document.createElement(\"h2\");\n  heading.textContent = \"On the desk\";\n  const count = document.createElement(\"p\");\n  count.className = \"mega-count\";\n  count.textContent = \"0 online\";\n  head.append(heading, count);\n\n  const list = document.createElement(\"div\");\n  list.className = \"mega-grid\";\n\n  const foot = document.createElement(\"div\");\n  foot.className = \"mega-foot\";\n  const another = document.createElement(\"button\");\n  another.type = \"button\";\n  another.className = \"text-btn\";\n  another.textContent = \"Use another name\";\n  another.addEventListener(\"click\", () => onAnotherName());\n  foot.append(another);\n\n  panel.append(head, list, foot);\n  anchor.append(button, panel);\n\n  const cluster = document.createElement(\"div\");\n  cluster.className = \"menu-cluster\";\n  cluster.append(field, anchor);\n\n  bar.append(brand, status, cluster);\n  menuBar.append(bar);\n\n  function setOpen(open) {\n    panel.hidden = !open;\n    button.setAttribute(\"aria-expanded\", open ? \"true\" : \"false\");\n  }\n\n  function showCount(total) {\n    onlineCount.textContent = String(total);\n    button.setAttribute(\"aria-label\", `Who is on the desk, ${total} online`);\n  }\n\n  button.addEventListener(\"click\", () => setOpen(panel.hidden));\n  const unwatchOnline = watchOnlineUsers((users) => showCount(users.length));\n\n  return {\n    button,\n    panel,\n    list,\n    count,\n    unwatchOnline,\n    close() {\n      setOpen(false);\n    },\n    setStatus(text, kind) {\n      status.textContent = text;\n      status.className = `status${kind ? ` ${kind}` : \"\"}`;\n    },\n    setName(next) {\n      fieldName.textContent = next;\n    },\n  };\n}\n",
  "/menu_bar/online_users.js": "// The live array of everyone currently on the desk.\n// Login and logout replace this array. The three-heads icon reads its length.\n\nconst onlineUsers = [];\nconst listeners = new Set();\n\nexport function getOnlineUsers() {\n  return onlineUsers;\n}\n\nexport function setOnlineUsers(next) {\n  const incoming = Array.isArray(next) ? next : [];\n  onlineUsers.splice(0, onlineUsers.length, ...incoming);\n  const snapshot = onlineUsers.slice();\n  for (const listener of listeners) listener(snapshot);\n  return onlineUsers.length;\n}\n\nexport function watchOnlineUsers(listener) {\n  listeners.add(listener);\n  listener(onlineUsers.slice());\n  return () => listeners.delete(listener);\n}\n",
  "/menu_bar/populate/populate.js": "export function populateMenu(list, users, { clientId, onToggle, count }) {\n  list.replaceChildren();\n  const online = Array.isArray(users) ? users : [];\n  if (count) count.textContent = online.length === 1 ? \"1 online\" : `${online.length} online`;\n\n  if (online.length === 0) {\n    const empty = document.createElement(\"p\");\n    empty.className = \"mega-empty\";\n    empty.textContent = \"Nobody is on the desk yet.\";\n    list.append(empty);\n    return;\n  }\n\n  for (const user of online) {\n    const card = document.createElement(\"article\");\n    card.className = \"person\";\n    if (user.id === clientId) card.classList.add(\"mine\");\n\n    const tone = user.color === \"red\" ? \"red\" : \"green\";\n\n    const avatar = document.createElement(\"span\");\n    avatar.className = `avatar ${tone}`;\n    avatar.textContent = initials(user.name);\n\n    const body = document.createElement(\"div\");\n    body.className = \"person-body\";\n\n    const name = document.createElement(\"p\");\n    name.className = `person-name ${tone}`;\n    name.textContent = user.name;\n    if (user.id === clientId) {\n      const you = document.createElement(\"span\");\n      you.className = \"you-tag\";\n      you.textContent = \"you\";\n      name.append(you);\n    }\n\n    const meta = document.createElement(\"p\");\n    meta.className = \"person-meta\";\n    meta.textContent = tone === \"red\" ? \"Red · online\" : \"Green · online\";\n    body.append(name, meta);\n\n    const button = document.createElement(\"button\");\n    button.type = \"button\";\n    button.className = \"toggle\";\n    button.textContent = \"Toggle\";\n    button.addEventListener(\"click\", () => onToggle(user.id));\n\n    card.append(avatar, body, button);\n    list.append(card);\n  }\n}\n\nfunction initials(name) {\n  const parts = String(name || \"\").trim().split(/\\s+/).slice(0, 2);\n  const letters = parts.map((part) => part[0] || \"\").join(\"\").toUpperCase();\n  return letters || \"?\";\n}\n"
};
